-- Q13 [Foramen Ovale & Ductus Arteriosus | medium | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub13$Foramen Ovale & Ductus Arteriosus$sub13$, $qt13$A near-term fetus has not yet taken a breath, so its lungs remain uninflated and collapsed. Considering the relative resistance of the vascular beds available to it, a physiologist predicts where most blood leaving the right side of the heart will travel.$qt13$, $op13$[{"label": "A", "text": "Toward the aorta, because uninflated pulmonary vessels offer high resistance while the aorta offers much lower resistance."}, {"label": "B", "text": "Toward the pulmonary circuit, because uninflated pulmonary vessels offer low resistance while the aorta offers much higher resistance."}, {"label": "C", "text": "Toward the aorta, because the placenta actively pumps fetal blood past the lungs and generates the pressure driving shunt flow."}, {"label": "D", "text": "Toward the aorta, because the pulmonary veins are not yet joined to the left atrium, leaving the shunts as the only outlet."}]$op13$::jsonb, 'A', $ex13$This is a Biology question that falls under the content category 'Fetal Circulation & Birth'. The answer is A because blood, like any fluid, preferentially follows the path of least resistance, and in the fetus that path leads away from the lungs and into the systemic circuit. The text states that "Blood vessels of uninflated lungs have high resistance to flow, a condition that encourages blood to flow to the aorta, which presents much lower resistance." This pressure relationship is precisely what makes the two shunts effective: the foramen ovale diverts blood from the right atrium to the left atrium, and the ductus arteriosus diverts blood from the pulmonary trunk into the aorta, so "only a small volume of oxygenated blood passes through the immature pulmonary circuit." (Choice A) Correct: the high resistance of the collapsed pulmonary bed versus the low resistance of the aorta is exactly the hemodynamic driver the textbook describes. (Choice B) Incorrect: this reverses the resistance relationship; the uninflated lungs have high, not low, resistance, which is why blood avoids them. (Choice C) Incorrect: the placenta is the organ of gas and nutrient exchange, not a pump; it does not generate the pressure that forces blood through the shunts. (Choice D) Incorrect: the pulmonary circuit is functional enough to return some blood to the left atrium, where freshly shunted blood mixes with "deoxygenated blood returning from the pulmonary circuit," so the shunts are not the only available outlet. This is a Scientific Reasoning and Problem Solving question because it requires applying the principle that flow follows the lower-resistance path to a described physiological scenario and predicting the destination of fetal blood rather than recalling a stated fact.$ex13$, 'medium', '3B', $cc13$Fetal Circulation & Birth$cc13$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a13B$Inverts which vascular bed carries higher resistance, concluding blood favors the pulmonary circuit$a13B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a13C$Treats the placenta as an active pump driving shunt flow rather than an exchange organ$a13C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a13D$Claims the pulmonary veins are unconnected so shunts are the sole outlet, when the pulmonary circuit minimally returns blood to the left atrium$a13D$ FROM q;

-- Q14 [Foramen Ovale & Ductus Arteriosus | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub14$Foramen Ovale & Ductus Arteriosus$sub14$, $qt14$A newborn is found to have a patent ductus arteriosus that remains fully open weeks after birth, by which point the lungs have inflated and the normal postnatal pressure relationship between the aorta and the pulmonary trunk is established. A clinician asks a student to predict the net direction of blood flow through this persistent vessel and its immediate consequence for the lungs.$qt14$, $op14$[{"label": "A", "text": "Blood flows from the higher-pressure pulmonary trunk into the lower-pressure aorta, just as it did in the fetus, sparing the lungs from extra flow."}, {"label": "B", "text": "Blood flows from the higher-pressure aorta into the lower-pressure pulmonary trunk, raising pulmonary pressure and overloading the lungs."}, {"label": "C", "text": "Blood flows from the left atrium into the right atrium through the opening, raising right-heart filling volume and overloading the lungs."}, {"label": "D", "text": "Blood flow through the vessel ceases entirely because its surrounding smooth muscle has permanently constricted, sparing the lungs from extra flow."}]$op14$::jsonb, 'B', $ex14$This is a Biology question that falls under the content category 'Fetal Circulation & Birth'. The answer is B because, once the newborn breathes and the postnatal pressure relationship is set, the aorta carries higher pressure than the pulmonary trunk, so blood in a vessel still joining the two is driven from aorta to pulmonary trunk. The text states that "Failure of the ductus arteriosus to close results in blood flowing from the higher pressure aorta into the lower pressure pulmonary trunk," and that "This additional fluid moving toward the lungs increases pulmonary pressure and makes respiration difficult." During fetal life flow ran the opposite way—from pulmonary trunk into aorta—because the noninflated lungs imposed high resistance; reversal of the pressure gradient after birth reverses the flow direction through any vessel that fails to close. (Choice A) reverses the postnatal gradient: it describes fetal-state flow ("Most of the blood pumped from the right ventricle into the pulmonary trunk is thereby diverted into the aorta"), which no longer holds once pulmonary pressure falls. (Choice B) is correct because the higher aortic pressure drives blood into the pulmonary trunk, increasing pulmonary pressure. (Choice C) describes a patent foramen ovale, a different shunt that "allows blood to flow from the right atrium to the left atrium," not flow through the ductus arteriosus. (Choice D) is a partial truth: rising oxygen normally makes "the smooth muscles in the wall of the ductus arteriosus constrict, sealing off the passage," but in a patent ductus arteriosus that closure has failed, so flow continues rather than ceasing. This is a Scientific Reasoning and Problem Solving question because it requires predicting flow direction from a reversed pressure gradient and then chaining that to the downstream consequence of pulmonary overload, rather than recalling a single stated fact.$ex14$, 'hard', '3B', $cc14$Fetal Circulation & Birth$cc14$, 'biology', 2, 160
  ) RETURNING id
)
