-- Q15 [Foramen Ovale & Ductus Arteriosus | hard | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub15$Foramen Ovale & Ductus Arteriosus$sub15$, $qt15$A full-term newborn takes its first breaths; the lungs and pulmonary vessels expand, and a clinician notes that the foramen ovale has sealed while the ductus arteriosus closes by a different trigger. Which event is responsible for closing the foramen ovale specifically?$qt15$, $op15$[{"label": "A", "text": "A rise in blood oxygen makes smooth muscle in the wall of the foramen ovale constrict, sealing the opening."}, {"label": "B", "text": "The drop in left-atrial pressure after the first breath pulls the valve flap open against the septum, sealing the opening."}, {"label": "C", "text": "The rise in left-atrial pressure once the newborn breathes pushes the valve flap against the septum, sealing the opening."}, {"label": "D", "text": "Severing of the umbilical cord halts placental return and collapses the foramen ovale within seconds, sealing the opening."}]$op15$::jsonb, 'C', $ex15$This is a Biology question that falls under the content category 'Fetal Circulation & Birth'. The answer is C because the foramen ovale closes mechanically when breathing reconfigures atrial pressures, not through an oxygen-sensing or cord-severing trigger. With the first breath the lungs and pulmonary vessels expand, pulmonary resistance falls, and pulmonary venous return raises left-atrial pressure; the text states that 'as the newborn begins to breathe and blood pressure in the atria increases, this shunt closes,' so the elevated pressure on the left side pushes the septum primum valve flap against the interatrial septum and seals the opening (the flap 'previously acted as a valve'). This is mechanistically distinct from the ductus arteriosus, which closes because 'as the amount of oxygen increases, the smooth muscles in the wall of the ductus arteriosus constrict,' and from the ductus venosus, which only becomes nonfunctional 'once the umbilical cord is severed.' (Choice A) Oxygen-driven smooth-muscle constriction is the closure mechanism of the ductus arteriosus, not the valve-flap foramen ovale, which lacks such a contractile wall. (Choice B) Atrial pressure on the left side rises rather than falls after the first breath, and a falling pressure would tend to hold the one-way flap open rather than seal it. (Choice C) The breathing-driven rise in left-atrial pressure presses the septum primum flap shut, which is correct. (Choice D) Cord severing chiefly affects the slower-closing ductus venosus, whereas the foramen ovale closes from the breathing-driven atrial pressure change, not loss of placental return. This is a Scientific Reasoning and Problem Solving question because it requires tracing the physiological cause-and-effect chain from lung inflation to a specific atrial pressure change and distinguishing it from the parallel oxygen-driven mechanism that closes a different shunt.$ex15$, 'hard', '3B', $cc15$Fetal Circulation & Birth$cc15$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a15A$Applying the ductus arteriosus oxygen-driven smooth-muscle constriction mechanism to the foramen ovale$a15A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a15B$Reversing the direction of the atrial pressure change (drop instead of rise) so closure is mis-attributed$a15B$ FROM q
