-- Q16 [Ductus Venosus & Fetal vs Adult Circulation | easy | Skill 1 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub16$Ductus Venosus & Fetal vs Adult Circulation$sub16$, $qt16$In a healthy near-term human fetus, freshly oxygenated blood arriving from the placenta via the umbilical vein is largely diverted through the ductus venosus before reaching the heart. This shunt allows that blood to bypass which fetal structure on its way to the inferior vena cava?$qt16$, $op16$[{"label": "A", "text": "The fetal lungs, so that oxygenated blood reaches the systemic circuit"}, {"label": "B", "text": "The fetal kidneys, so that placental blood avoids premature filtration"}, {"label": "C", "text": "The fetal right atrium, so that blood reaches the left atrium directly"}, {"label": "D", "text": "The fetal liver, so that oxygenated blood passes almost directly into the inferior vena cava"}]$op16$::jsonb, 'D', $ex16$This is a Biology question that falls under the content category 'Fetal Circulation & Birth'. The answer is D because the ductus venosus is the shunt that branches from the umbilical vein and lets freshly oxygenated placental blood bypass the fetal liver, carrying it directly to the inferior vena cava and onward to the heart. The text states that this shunt allows "much of the freshly oxygenated blood from the placenta...to bypass the fetal liver and go directly to the fetal heart," and the Key Terms define the ductus venosus as the "shunt that causes oxygenated blood to bypass the fetal liver on its way to the inferior vena cava." The semifunctional fetal liver receives only a trickle of blood, which is all it needs at that immature stage. (Choice A) The lungs are bypassed by two different shunts—the foramen ovale and the ductus arteriosus—not by the ductus venosus, so this reverses which shunt serves which organ. (Choice B) No fetal shunt routes blood around the kidneys; the kidneys are not bypassed, and the ductus venosus specifically bypasses the liver. (Choice C) Bypassing the right atrium to deliver blood directly toward the left atrium is the role of the foramen ovale, not the ductus venosus, which acts upstream at the level of the umbilical vein and inferior vena cava. (Choice D) The ductus venosus shunts umbilical-vein blood around the fetal liver and into the inferior vena cava, which is correct. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the defined anatomical role of a specific fetal shunt and the organ it bypasses.$ex16$, 'easy', '3B', $cc16$Fetal Circulation & Birth$cc16$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a16A$Attributes the lung-bypassing function (foramen ovale / ductus arteriosus) to the ductus venosus, swapping which shunt serves which organ$a16A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a16B$Invents a nonexistent kidney-bypassing shunt to 'protect' placental blood from filtration$a16B$ FROM q
