-- Q17 [Ductus Venosus & Fetal vs Adult Circulation | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub17$Ductus Venosus & Fetal vs Adult Circulation$sub17$, $qt17$During a newborn's first weeks of life, the temporary vessel that had branched from the umbilical vein to carry oxygenated placental blood past the liver slowly closes and degenerates into a fibrous cord lying beneath the liver. This adult fibrous remnant is named the:$qt17$, $op17$[{"label": "A", "text": "ligamentum arteriosum, a fibrous cord left in place of a former fetal shunt"}, {"label": "B", "text": "fossa ovalis, a depression marking a former fetal shunt in the interatrial septum"}, {"label": "C", "text": "ligamentum venosum, a fibrous cord lying beneath the liver"}, {"label": "D", "text": "round ligament of the liver (ligamentum teres), a cord left by an obliterated fetal vessel"}]$op17$::jsonb, 'C', $ex17$This is a Biology question that falls under the content category 'Fetal Circulation & Birth'. The answer is C because the ductus venosus, the temporary vessel that branches from the umbilical vein to shunt oxygenated placental blood past the fetal liver, closes during the first weeks of infancy and degenerates into the ligamentum venosum, a fibrotic remnant beneath the liver. OpenStax A&P 2e states the ductus venosus 'closes slowly during the first weeks of infancy and degenerates to become the ligamentum venosum,' and elsewhere that 'The ductus venosus degenerates to become the ligamentum venosum beneath the liver.' The scenario describes exactly this vessel (branching from the umbilical vein, bypassing the liver) and its postnatal fate. (Choice A) The ligamentum arteriosum is the connective-tissue remnant of the ductus arteriosus, the shunt connecting the pulmonary trunk to the aorta, not of the ductus venosus. (Choice B) The fossa ovalis is the depression that remains in the interatrial septum after the foramen ovale closes, marking a different fetal shunt. (Choice C) The ligamentum venosum is correct, as it is the fibrous remnant beneath the liver left when the ductus venosus degenerates. (Choice D) The round ligament of the liver (ligamentum teres hepatis) is a remnant of the umbilical vein itself, not of the ductus venosus. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the specific adult anatomical remnant into which a named fetal vessel degenerates.$ex17$, 'easy', '3B', $cc17$Fetal Circulation & Birth$cc17$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a17A$Names the remnant of a different (sibling) fetal shunt — ligamentum arteriosum from the ductus arteriosus$a17A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a17B$Names the remnant of the foramen ovale (interatrial septum), a different fetal shunt$a17B$ FROM q
